mapper.update:
UPDATE CONTRACT_CANDIDATE
SET PROMOTION_STATE='PROMOTED', VERSION_NO=VERSION_NO+1,
    PROMOTED_CONTRACT_ID=#{contractId}, PROMOTED_BY=#{promotedBy},
    PROMOTED_AT=#{promotedAt}, UPDATED_AT=#{updatedAt}
WHERE PROJECT_ID=#{projectId} AND ID=#{candidateId}
  AND PROMOTION_STATE='DRAFT' AND VERSION_NO=#{expectedVersion}

UPDATE CONTRACT_CANDIDATE
SET PROMOTION_STATE='PROMOTED', VERSION_NO=VERSION_NO+1,
    PROMOTED_CONTRACT_ID=#{contractId}, PROMOTED_CONFIRMATION_ID=#{confirmationId},
    PROMOTED_BY=#{promotedBy}, PROMOTED_AT=#{promotedAt}, UPDATED_AT=#{updatedAt}
WHERE PROJECT_ID=#{projectId} AND ID=#{candidateId}
  AND PROMOTION_STATE='DRAFT' AND VERSION_NO=#{expectedVersion}

UPDATE CONTRACT_CANDIDATE SET VERSION_NO=VERSION_NO+1, UPDATED_AT=#{updatedAt}
WHERE PROJECT_ID=#{projectId} AND ID=#{candidateId}
  AND PROMOTION_STATE='DRAFT' AND VERSION_NO=#{expectedVersion}

UPDATE CONTRACT_CANDIDATE
SET SOURCE_PARSE_RESULT_ID=#{parseResultId}, SOURCE_ROLE_DECISION_ID=#{roleDecisionId},
    SOURCE_IDENTITY_DECISION_ID=#{identityDecisionId},
    SOURCE_AUTHORITY_SOURCE=#{authoritySource},
    SOURCE_FACT_FINGERPRINT=#{factFingerprint}, VERSION_NO=VERSION_NO+1,
    UPDATED_AT=#{updatedAt}
WHERE PROJECT_ID=#{projectId} AND ID=#{candidateId}
  AND PROMOTION_STATE='DRAFT' AND VERSION_NO=#{expectedVersion}
